# Google Day 1: Simple ReAct Agent Skeleton
class ReActAgent:
    def __init__(self, model, tools):
        self.model = model
        self.tools = tools

    def run(self, task_spec):
        thought = self.model.think(f'Goal: {task_spec}')
        while not task_spec.is_satisfied():
            action = self.model.plan_action(thought)
            observation = self.tools.execute(action)
            thought = self.model.reflect(observation)
        return 'Task Successfully Completed'

